-- TestDock multi-platform database design draft, 2026-10-25.
-- PostgreSQL 17 syntax reference; no extensions or external services required by this DDL.
-- REVIEW ONLY: not an applied migration; use an isolated empty database after approval.
-- UUID values are generated by the platform. All references default to NO ACTION.
-- See database-design.md for service-enforced invariants, lifecycle, authorization and retention.
-- This file creates schema only: no DROP / DELETE / TRUNCATE or sample private data.
BEGIN;

-- 项目: 产品级隔离单元，Android、iOS、Web 应用归属于同一项目。
CREATE TABLE projects (
    id uuid PRIMARY KEY,
    code text NOT NULL UNIQUE,
    name text NOT NULL,
    archived_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE projects IS '产品级隔离单元，Android、iOS、Web 应用归属于同一项目。';
COMMENT ON COLUMN projects.id IS '项目 UUID';
COMMENT ON COLUMN projects.code IS '稳定项目代号';
COMMENT ON COLUMN projects.name IS '展示名称';
COMMENT ON COLUMN projects.archived_at IS '归档时间，保留历史引用';
COMMENT ON COLUMN projects.created_at IS '创建时间，统一 UTC';

-- 项目成员: 复用身份提供方，以项目角色授权，不在业务库保存登录口令。
CREATE TABLE project_members (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    identity_issuer text NOT NULL,
    identity_subject text NOT NULL,
    role text NOT NULL CHECK (role IN ('owner','maintainer','runner','viewer')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, identity_issuer, identity_subject)
);
COMMENT ON TABLE project_members IS '复用身份提供方，以项目角色授权，不在业务库保存登录口令。 角色必须由后端检查；project_id 外键不等于行级访问控制。';
COMMENT ON COLUMN project_members.id IS '服务端生成 UUID';
COMMENT ON COLUMN project_members.project_id IS '项目归属';
COMMENT ON COLUMN project_members.identity_issuer IS '身份提供方标识';
COMMENT ON COLUMN project_members.identity_subject IS '提供方内稳定用户 ID';
COMMENT ON COLUMN project_members.role IS '项目角色';
COMMENT ON COLUMN project_members.created_at IS '创建时间，统一 UTC';

-- 应用: 目标端属于应用，不为每种端复制一套任务和报告表。
CREATE TABLE applications (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    platform text NOT NULL CHECK (platform IN ('android','ios','web')),
    name text NOT NULL,
    identifier text NOT NULL,
    archived_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, id, platform),
    UNIQUE (project_id, platform, identifier)
);
COMMENT ON TABLE applications IS '目标端属于应用，不为每种端复制一套任务和报告表。';
COMMENT ON COLUMN applications.id IS '服务端生成 UUID';
COMMENT ON COLUMN applications.project_id IS '项目归属';
COMMENT ON COLUMN applications.platform IS '目标端，新增端通过迁移扩展';
COMMENT ON COLUMN applications.name IS '应用名称';
COMMENT ON COLUMN applications.identifier IS '包名、Bundle ID 或站点逻辑标识';
COMMENT ON COLUMN applications.archived_at IS '归档时间';
COMMENT ON COLUMN applications.created_at IS '创建时间，统一 UTC';

-- 应用构建: 固定待测构建；移动包与 Web 部署均采用同一版本记录。
CREATE TABLE app_builds (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    application_id uuid NOT NULL,
    version text NOT NULL,
    build_key text NOT NULL,
    source_commit text,
    storage_key text,
    sha256 text CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, application_id, id),
    UNIQUE (project_id, application_id, build_key),
    FOREIGN KEY (project_id, application_id) REFERENCES applications(project_id, id),
    CHECK (jsonb_typeof(metadata) = 'object')
);
COMMENT ON TABLE app_builds IS '固定待测构建；移动包与 Web 部署均采用同一版本记录。';
COMMENT ON COLUMN app_builds.id IS '服务端生成 UUID';
COMMENT ON COLUMN app_builds.project_id IS '项目归属';
COMMENT ON COLUMN app_builds.application_id IS '所属应用';
COMMENT ON COLUMN app_builds.version IS '业务版本';
COMMENT ON COLUMN app_builds.build_key IS 'CI 构建号或部署版本，不使用可变 latest';
COMMENT ON COLUMN app_builds.source_commit IS '来源提交号';
COMMENT ON COLUMN app_builds.storage_key IS '包文件存储键；Web 部署可为空';
COMMENT ON COLUMN app_builds.sha256 IS '包校验摘要';
COMMENT ON COLUMN app_builds.metadata IS '包属性或部署元数据';
COMMENT ON COLUMN app_builds.created_at IS '创建时间，统一 UTC';

-- 测试环境: 保存各环境的非敏感配置，实际站点地址可随环境区分。
CREATE TABLE environments (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    name text NOT NULL,
    config jsonb NOT NULL DEFAULT '{}'::jsonb,
    secret_ref text,
    archived_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, name),
    CHECK (jsonb_typeof(config) = 'object')
);
COMMENT ON TABLE environments IS '保存各环境的非敏感配置，实际站点地址可随环境区分。';
COMMENT ON COLUMN environments.id IS '服务端生成 UUID';
COMMENT ON COLUMN environments.project_id IS '项目归属';
COMMENT ON COLUMN environments.name IS 'staging、qa 等环境名';
COMMENT ON COLUMN environments.config IS '地址映射、变量及 schemaVersion；禁止明文凭据';
COMMENT ON COLUMN environments.secret_ref IS '密钥管理系统引用，不能是密钥值';
COMMENT ON COLUMN environments.archived_at IS '归档时间';
COMMENT ON COLUMN environments.created_at IS '创建时间，统一 UTC';

-- 执行节点: 宿主 Agent 与可用适配器，初期按项目独占。
CREATE TABLE execution_nodes (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    name text NOT NULL,
    agent_version text NOT NULL,
    capabilities jsonb NOT NULL DEFAULT '{}'::jsonb,
    status text NOT NULL CHECK (status IN ('online','offline','draining')),
    heartbeat_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, name),
    CHECK (jsonb_typeof(capabilities) = 'object')
);
COMMENT ON TABLE execution_nodes IS '宿主 Agent 与可用适配器，初期按项目独占。 宿主凭据不入 capabilities；首期不设计跨项目共享节点池。';
COMMENT ON COLUMN execution_nodes.id IS '服务端生成 UUID';
COMMENT ON COLUMN execution_nodes.project_id IS '项目归属';
COMMENT ON COLUMN execution_nodes.name IS '节点名称';
COMMENT ON COLUMN execution_nodes.agent_version IS 'Agent 版本';
COMMENT ON COLUMN execution_nodes.capabilities IS '已注册适配器及其版本';
COMMENT ON COLUMN execution_nodes.status IS '节点状态';
COMMENT ON COLUMN execution_nodes.heartbeat_at IS '最近心跳时间';
COMMENT ON COLUMN execution_nodes.created_at IS '创建时间，统一 UTC';

-- 资源档案: 不可变的可比性档案：系统、设备或浏览器、采集器、分辨率、指标版本。
CREATE TABLE resource_profiles (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    platform text NOT NULL CHECK (platform IN ('android','ios','web')),
    name text NOT NULL,
    fingerprint text NOT NULL CHECK (fingerprint ~ '^[0-9a-f]{64}$'),
    spec jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, id, platform),
    UNIQUE (project_id, platform, fingerprint),
    CHECK (jsonb_typeof(spec) = 'object')
);
COMMENT ON TABLE resource_profiles IS '不可变的可比性档案：系统、设备或浏览器、采集器、分辨率、指标版本。 档案内容变化新增记录，不覆盖旧记录；性能比较还须校验应用、场景和指标口径。';
COMMENT ON COLUMN resource_profiles.id IS '服务端生成 UUID';
COMMENT ON COLUMN resource_profiles.project_id IS '项目归属';
COMMENT ON COLUMN resource_profiles.platform IS '目标端';
COMMENT ON COLUMN resource_profiles.name IS '档案展示名';
COMMENT ON COLUMN resource_profiles.fingerprint IS '规范化档案的 SHA-256';
COMMENT ON COLUMN resource_profiles.spec IS '结构化档案及 schemaVersion';
COMMENT ON COLUMN resource_profiles.created_at IS '创建时间，统一 UTC';

-- 执行实例: 真机、模拟器或浏览器槽位。每个实例只承载一个活动运行。
CREATE TABLE execution_resources (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    node_id uuid NOT NULL,
    profile_id uuid NOT NULL,
    platform text NOT NULL CHECK (platform IN ('android','ios','web')),
    resource_key text NOT NULL,
    kind text NOT NULL CHECK (kind IN ('device','simulator','browser_slot')),
    status text NOT NULL CHECK (status IN ('ready','offline','unauthorized','draining')),
    fence_counter bigint NOT NULL DEFAULT 0 CHECK (fence_counter >= 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, id, platform),
    UNIQUE (project_id, node_id, resource_key),
    FOREIGN KEY (project_id, node_id) REFERENCES execution_nodes(project_id, id),
    FOREIGN KEY (project_id, profile_id, platform) REFERENCES resource_profiles(project_id, id, platform),
    CHECK ((platform = 'web' AND kind = 'browser_slot') OR (platform <> 'web' AND kind IN ('device','simulator')))
);
COMMENT ON TABLE execution_resources IS '真机、模拟器或浏览器槽位。每个实例只承载一个活动运行。 Web 并发通过多个独立槽位表示；资源重新建档须在无活动租约时处理。';
COMMENT ON COLUMN execution_resources.id IS '服务端生成 UUID';
COMMENT ON COLUMN execution_resources.project_id IS '项目归属';
COMMENT ON COLUMN execution_resources.node_id IS '执行节点';
COMMENT ON COLUMN execution_resources.profile_id IS '当前不可变档案';
COMMENT ON COLUMN execution_resources.platform IS '目标端';
COMMENT ON COLUMN execution_resources.resource_key IS '宿主内设备标识或浏览器槽位';
COMMENT ON COLUMN execution_resources.kind IS '资源类型';
COMMENT ON COLUMN execution_resources.status IS '连接状态；占用从租约推导';
COMMENT ON COLUMN execution_resources.fence_counter IS '每次分配递增的隔离令牌';
COMMENT ON COLUMN execution_resources.created_at IS '创建时间，统一 UTC';

-- 测试套件: 登记代码维护的 UI 用例或性能场景，不把脚本正文塞进数据库。
CREATE TABLE test_suites (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    application_id uuid NOT NULL,
    name text NOT NULL,
    test_type text NOT NULL CHECK (test_type IN ('ui','performance','joint')),
    archived_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, application_id, id),
    UNIQUE (project_id, application_id, name),
    FOREIGN KEY (project_id, application_id) REFERENCES applications(project_id, id)
);
COMMENT ON TABLE test_suites IS '登记代码维护的 UI 用例或性能场景，不把脚本正文塞进数据库。';
COMMENT ON COLUMN test_suites.id IS '服务端生成 UUID';
COMMENT ON COLUMN test_suites.project_id IS '项目归属';
COMMENT ON COLUMN test_suites.application_id IS '所属应用';
COMMENT ON COLUMN test_suites.name IS '套件或场景名';
COMMENT ON COLUMN test_suites.test_type IS '测试类型；joint 为编排';
COMMENT ON COLUMN test_suites.archived_at IS '归档时间';
COMMENT ON COLUMN test_suites.created_at IS '创建时间，统一 UTC';

-- 套件版本: 固定仓库、提交及选择器，旧运行可追溯到当时的用例。
CREATE TABLE suite_versions (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    application_id uuid NOT NULL,
    suite_id uuid NOT NULL,
    version integer NOT NULL CHECK (version > 0),
    source_ref text NOT NULL,
    source_commit text NOT NULL,
    manifest jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, application_id, id),
    UNIQUE (project_id, suite_id, version),
    FOREIGN KEY (project_id, application_id, suite_id) REFERENCES test_suites(project_id, application_id, id),
    CHECK (jsonb_typeof(manifest) = 'object')
);
COMMENT ON TABLE suite_versions IS '固定仓库、提交及选择器，旧运行可追溯到当时的用例。';
COMMENT ON COLUMN suite_versions.id IS '服务端生成 UUID';
COMMENT ON COLUMN suite_versions.project_id IS '项目归属';
COMMENT ON COLUMN suite_versions.application_id IS '应用关联约束';
COMMENT ON COLUMN suite_versions.suite_id IS '逻辑套件';
COMMENT ON COLUMN suite_versions.version IS '套件修订序号';
COMMENT ON COLUMN suite_versions.source_ref IS '不含凭据的仓库或受控用例来源';
COMMENT ON COLUMN suite_versions.source_commit IS '固定提交标识';
COMMENT ON COLUMN suite_versions.manifest IS '用例 key、入口、场景及 schemaVersion';
COMMENT ON COLUMN suite_versions.created_at IS '创建时间，统一 UTC';

-- 测试任务: 用户可编辑的逻辑任务；不存通过或失败结果。
CREATE TABLE test_tasks (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    application_id uuid NOT NULL,
    name text NOT NULL,
    lifecycle text NOT NULL DEFAULT 'draft' CHECK (lifecycle IN ('draft','ready','archived')),
    lock_version integer NOT NULL DEFAULT 1 CHECK (lock_version > 0),
    created_by text NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT now(),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, application_id, id),
    FOREIGN KEY (project_id, application_id) REFERENCES applications(project_id, id)
);
COMMENT ON TABLE test_tasks IS '用户可编辑的逻辑任务；不存通过或失败结果。 Web/iOS 未接入时只能是 draft；计划能力不能用设备数据冒充已就绪。';
COMMENT ON COLUMN test_tasks.id IS '服务端生成 UUID';
COMMENT ON COLUMN test_tasks.project_id IS '项目归属';
COMMENT ON COLUMN test_tasks.application_id IS '所属应用';
COMMENT ON COLUMN test_tasks.name IS '任务名';
COMMENT ON COLUMN test_tasks.lifecycle IS '配置生命周期，非执行状态';
COMMENT ON COLUMN test_tasks.lock_version IS '乐观锁版本';
COMMENT ON COLUMN test_tasks.created_by IS '身份主体或服务账号引用';
COMMENT ON COLUMN test_tasks.updated_at IS '服务端更新时显式赋值';
COMMENT ON COLUMN test_tasks.created_at IS '创建时间，统一 UTC';

-- 任务配置版本: 每次保存新增不可变修订；运行只引用已验证修订。
CREATE TABLE task_revisions (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    application_id uuid NOT NULL,
    task_id uuid NOT NULL,
    revision integer NOT NULL CHECK (revision > 0),
    environment_id uuid NOT NULL,
    build_id uuid,
    suite_version_id uuid,
    test_type text NOT NULL CHECK (test_type IN ('ui','performance','joint')),
    readiness text NOT NULL DEFAULT 'draft' CHECK (readiness IN ('draft','validated')),
    config jsonb NOT NULL,
    created_by text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, application_id, id),
    UNIQUE (project_id, task_id, revision),
    FOREIGN KEY (project_id, application_id, task_id) REFERENCES test_tasks(project_id, application_id, id),
    FOREIGN KEY (project_id, environment_id) REFERENCES environments(project_id, id),
    FOREIGN KEY (project_id, application_id, build_id) REFERENCES app_builds(project_id, application_id, id),
    FOREIGN KEY (project_id, application_id, suite_version_id) REFERENCES suite_versions(project_id, application_id, id),
    CHECK (jsonb_typeof(config) = 'object'),
    CHECK (readiness = 'draft' OR (build_id IS NOT NULL AND suite_version_id IS NOT NULL))
);
COMMENT ON TABLE task_revisions IS '每次保存新增不可变修订；运行只引用已验证修订。 只有字段完整不代表可运行；适配器能力、套件类型及配置 schema 仍由提交事务验证。';
COMMENT ON COLUMN task_revisions.id IS '服务端生成 UUID';
COMMENT ON COLUMN task_revisions.project_id IS '项目归属';
COMMENT ON COLUMN task_revisions.application_id IS '应用关联约束';
COMMENT ON COLUMN task_revisions.task_id IS '逻辑任务';
COMMENT ON COLUMN task_revisions.revision IS '配置版本号';
COMMENT ON COLUMN task_revisions.environment_id IS '环境';
COMMENT ON COLUMN task_revisions.build_id IS '草稿可缺构建，提交前校验';
COMMENT ON COLUMN task_revisions.suite_version_id IS '草稿可缺套件版本，提交前校验';
COMMENT ON COLUMN task_revisions.test_type IS '类型快照';
COMMENT ON COLUMN task_revisions.readiness IS '配置校验状态';
COMMENT ON COLUMN task_revisions.config IS '脱敏配置、资源需求、适配器及 schemaVersion';
COMMENT ON COLUMN task_revisions.created_by IS '保存者引用';
COMMENT ON COLUMN task_revisions.created_at IS '创建时间，统一 UTC';

-- 测试运行: 一次提交或重跑对应一行，保留执行状态、最终结论和当时配置。
CREATE TABLE test_runs (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    application_id uuid NOT NULL,
    platform text NOT NULL CHECK (platform IN ('android','ios','web')),
    revision_id uuid NOT NULL,
    parent_run_id uuid,
    request_key text NOT NULL,
    state text NOT NULL DEFAULT 'queued' CHECK (state IN ('queued','dispatching','running','finalizing','completed','errored','cancelled')),
    outcome text CHECK (outcome IN ('passed','failed','not_tested')),
    reason_code text,
    resource_id uuid,
    profile_id uuid,
    config_snapshot jsonb NOT NULL,
    lock_version integer NOT NULL DEFAULT 1 CHECK (lock_version > 0),
    started_at timestamptz,
    ended_at timestamptz,
    created_by text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, application_id, id),
    UNIQUE (project_id, id, resource_id),
    UNIQUE (project_id, request_key),
    FOREIGN KEY (project_id, application_id, platform) REFERENCES applications(project_id, id, platform),
    FOREIGN KEY (project_id, application_id, revision_id) REFERENCES task_revisions(project_id, application_id, id),
    FOREIGN KEY (project_id, application_id, parent_run_id) REFERENCES test_runs(project_id, application_id, id),
    FOREIGN KEY (project_id, resource_id, platform) REFERENCES execution_resources(project_id, id, platform),
    FOREIGN KEY (project_id, profile_id, platform) REFERENCES resource_profiles(project_id, id, platform),
    CHECK (jsonb_typeof(config_snapshot) = 'object'),
    CHECK ((state = 'completed' AND outcome IS NOT NULL) OR (state <> 'completed' AND outcome IS NULL)),
    CHECK ((state IN ('completed','errored','cancelled')) = (ended_at IS NOT NULL)),
    CHECK (state NOT IN ('running','finalizing','completed') OR (resource_id IS NOT NULL AND started_at IS NOT NULL)),
    CHECK ((resource_id IS NULL) = (profile_id IS NULL)),
    CHECK (ended_at IS NULL OR ended_at >= created_at),
    CHECK (started_at IS NULL OR started_at >= created_at),
    CHECK (ended_at IS NULL OR started_at IS NULL OR ended_at >= started_at)
);
COMMENT ON TABLE test_runs IS '一次提交或重跑对应一行，保留执行状态、最终结论和当时配置。 终态只追加新运行或新试算，不改原始结论；这种不可变性及状态转换须由后端写入边界实现。';
COMMENT ON COLUMN test_runs.id IS '服务端生成 UUID';
COMMENT ON COLUMN test_runs.project_id IS '项目归属';
COMMENT ON COLUMN test_runs.application_id IS '目标应用';
COMMENT ON COLUMN test_runs.platform IS '目标端查询维度';
COMMENT ON COLUMN test_runs.revision_id IS '固定任务修订';
COMMENT ON COLUMN test_runs.parent_run_id IS '重跑来源；同项目同应用';
COMMENT ON COLUMN test_runs.request_key IS '项目内提交幂等键';
COMMENT ON COLUMN test_runs.state IS '执行状态，与测试结论分离';
COMMENT ON COLUMN test_runs.outcome IS '完成时的测试结论';
COMMENT ON COLUMN test_runs.reason_code IS '未判定、取消或基础设施错误原因码';
COMMENT ON COLUMN test_runs.resource_id IS '实际执行实例，排队时为空';
COMMENT ON COLUMN test_runs.profile_id IS '实际使用的固定档案';
COMMENT ON COLUMN test_runs.config_snapshot IS '固定配置、版本及脱敏环境快照';
COMMENT ON COLUMN test_runs.lock_version IS '状态更新 CAS 版本';
COMMENT ON COLUMN test_runs.started_at IS '实际开始时间';
COMMENT ON COLUMN test_runs.ended_at IS '终态时间';
COMMENT ON COLUMN test_runs.created_by IS '触发者引用';
COMMENT ON COLUMN test_runs.created_at IS '创建时间，统一 UTC';

-- 调试会话: 人工设备控制使用短期调试会话，与自动运行竞争同一资源租约。
CREATE TABLE debug_sessions (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    resource_id uuid NOT NULL,
    actor_ref text NOT NULL,
    state text NOT NULL CHECK (state IN ('opening','active','closing','closed','lost')),
    expires_at timestamptz NOT NULL,
    closed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, id, resource_id),
    FOREIGN KEY (project_id, resource_id) REFERENCES execution_resources(project_id, id),
    CHECK (expires_at > created_at),
    CHECK ((state IN ('closed','lost')) = (closed_at IS NOT NULL)),
    CHECK (closed_at IS NULL OR closed_at >= created_at)
);
COMMENT ON TABLE debug_sessions IS '人工设备控制使用短期调试会话，与自动运行竞争同一资源租约。 只读预览不占独占租约；会发送输入、冻结采集等操作按宿主冲突规则受控。断线不能立即释放资源。';
COMMENT ON COLUMN debug_sessions.id IS '调试会话 UUID';
COMMENT ON COLUMN debug_sessions.project_id IS '项目归属';
COMMENT ON COLUMN debug_sessions.resource_id IS '调试实例';
COMMENT ON COLUMN debug_sessions.actor_ref IS '操作人身份引用';
COMMENT ON COLUMN debug_sessions.state IS '调试生命周期';
COMMENT ON COLUMN debug_sessions.expires_at IS '会话过期时间';
COMMENT ON COLUMN debug_sessions.closed_at IS '关闭或确认失联时间';
COMMENT ON COLUMN debug_sessions.created_at IS '创建时间，统一 UTC';

-- 资源租约: 保留运行或调试的独占历史，用 fencing token 拒绝过期执行者。
CREATE TABLE resource_leases (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    resource_id uuid NOT NULL,
    run_id uuid,
    debug_session_id uuid,
    fencing_token bigint NOT NULL CHECK (fencing_token > 0),
    holder_id text NOT NULL,
    expires_at timestamptz NOT NULL,
    released_at timestamptz,
    release_reason text,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, resource_id, fencing_token),
    FOREIGN KEY (project_id, run_id, resource_id) REFERENCES test_runs(project_id, id, resource_id),
    CHECK (expires_at > created_at),
    CHECK (released_at IS NULL OR released_at >= created_at),
    FOREIGN KEY (project_id, debug_session_id, resource_id) REFERENCES debug_sessions(project_id, id, resource_id),
    CHECK ((run_id IS NOT NULL) <> (debug_session_id IS NOT NULL))
);
COMMENT ON TABLE resource_leases IS '保留运行或调试的独占历史，用 fencing token 拒绝过期执行者。 部分唯一索引保证每实例、运行或调试会话最多一条未释放租约；超时回收仍需 Agent 隔离旧进程。';
COMMENT ON COLUMN resource_leases.id IS '服务端生成 UUID';
COMMENT ON COLUMN resource_leases.project_id IS '项目归属';
COMMENT ON COLUMN resource_leases.resource_id IS '被占用实例';
COMMENT ON COLUMN resource_leases.run_id IS '自动运行归属，与调试会话二选一';
COMMENT ON COLUMN resource_leases.debug_session_id IS '人工调试归属，与运行二选一';
COMMENT ON COLUMN resource_leases.fencing_token IS '分配时递增并写入实例计数器';
COMMENT ON COLUMN resource_leases.holder_id IS 'Agent 实例标识，不含凭据';
COMMENT ON COLUMN resource_leases.expires_at IS '心跳到期时间';
COMMENT ON COLUMN resource_leases.released_at IS '显式释放，过期不等于安全释放';
COMMENT ON COLUMN resource_leases.release_reason IS '正常完成、取消确认、失联隔离等';
COMMENT ON COLUMN resource_leases.created_at IS '创建时间，统一 UTC';

-- 运行组件: 一次运行下的 UI/性能子结果。联动共用运行和租约，分别保留结论。
CREATE TABLE run_components (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    run_id uuid NOT NULL,
    kind text NOT NULL CHECK (kind IN ('ui','performance')),
    adapter_key text NOT NULL,
    adapter_version text NOT NULL,
    external_run_id text,
    state text NOT NULL CHECK (state IN ('pending','running','completed','errored','cancelled')),
    outcome text CHECK (outcome IN ('passed','failed','not_tested')),
    summary jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, run_id, id),
    UNIQUE (project_id, run_id, kind),
    FOREIGN KEY (project_id, run_id) REFERENCES test_runs(project_id, id),
    CHECK (jsonb_typeof(summary) = 'object'),
    CHECK ((state = 'completed' AND outcome IS NOT NULL) OR (state <> 'completed' AND outcome IS NULL))
);
COMMENT ON TABLE run_components IS '一次运行下的 UI/性能子结果。联动共用运行和租约，分别保留结论。';
COMMENT ON COLUMN run_components.id IS '服务端生成 UUID';
COMMENT ON COLUMN run_components.project_id IS '项目归属';
COMMENT ON COLUMN run_components.run_id IS '平台运行';
COMMENT ON COLUMN run_components.kind IS '子任务能力';
COMMENT ON COLUMN run_components.adapter_key IS '适配器名';
COMMENT ON COLUMN run_components.adapter_version IS '适配器版本';
COMMENT ON COLUMN run_components.external_run_id IS '组件原始 runId';
COMMENT ON COLUMN run_components.state IS '组件状态';
COMMENT ON COLUMN run_components.outcome IS '测试结论';
COMMENT ON COLUMN run_components.summary IS '计数、警告、完整性、原始 schemaVersion';
COMMENT ON COLUMN run_components.created_at IS '创建时间，统一 UTC';

-- 用例结果: 每个用例的执行尝试独立保存，可区分用例重试与整次重跑。
CREATE TABLE case_results (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    component_id uuid NOT NULL,
    case_key text NOT NULL,
    attempt integer NOT NULL DEFAULT 1 CHECK (attempt > 0),
    outcome text NOT NULL CHECK (outcome IN ('passed','failed','skipped','errored')),
    duration_ms bigint CHECK (duration_ms >= 0),
    error_summary text,
    steps jsonb NOT NULL DEFAULT '[]'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, component_id, case_key, attempt),
    FOREIGN KEY (project_id, component_id) REFERENCES run_components(project_id, id),
    CHECK (jsonb_typeof(steps) = 'array')
);
COMMENT ON TABLE case_results IS '每个用例的执行尝试独立保存，可区分用例重试与整次重跑。 后端只接受 UI 组件的用例记录，校验 case_key 属于固定 suite_version。';
COMMENT ON COLUMN case_results.id IS '服务端生成 UUID';
COMMENT ON COLUMN case_results.project_id IS '项目归属';
COMMENT ON COLUMN case_results.component_id IS 'UI 组件结果';
COMMENT ON COLUMN case_results.case_key IS '套件版本中的稳定用例 key';
COMMENT ON COLUMN case_results.attempt IS '同一次运行内用例尝试次数';
COMMENT ON COLUMN case_results.outcome IS '用例结果';
COMMENT ON COLUMN case_results.duration_ms IS '用例耗时';
COMMENT ON COLUMN case_results.error_summary IS '脱敏错误摘要';
COMMENT ON COLUMN case_results.steps IS '小体积步骤摘要；完整日志存证据文件';
COMMENT ON COLUMN case_results.created_at IS '创建时间，统一 UTC';

-- 证据文件: 保存文件元数据和私有存储键，截图、日志、录像、曲线均通过此表归档。
CREATE TABLE artifacts (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    run_id uuid NOT NULL,
    component_id uuid,
    logical_key text NOT NULL,
    kind text NOT NULL CHECK (kind IN ('screenshot','ui_tree','video','log','trace','metric_series','report_json','report_html','other')),
    storage_key text NOT NULL,
    mime_type text NOT NULL,
    byte_size bigint NOT NULL CHECK (byte_size >= 0),
    sha256 text NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    schema_version text,
    availability text NOT NULL DEFAULT 'available' CHECK (availability IN ('available','missing','expired')),
    expires_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, run_id, logical_key),
    UNIQUE (project_id, storage_key),
    FOREIGN KEY (project_id, run_id) REFERENCES test_runs(project_id, id),
    FOREIGN KEY (project_id, run_id, component_id) REFERENCES run_components(project_id, run_id, id)
);
COMMENT ON TABLE artifacts IS '保存文件元数据和私有存储键，截图、日志、录像、曲线均通过此表归档。 文件先写临时键并校验成功，再提交元数据；无法做到数据库与文件原子提交，需幂等补偿。';
COMMENT ON COLUMN artifacts.id IS '服务端生成 UUID';
COMMENT ON COLUMN artifacts.project_id IS '项目归属';
COMMENT ON COLUMN artifacts.run_id IS '运行归属';
COMMENT ON COLUMN artifacts.component_id IS '可选子组件归属；总体报告为空';
COMMENT ON COLUMN artifacts.logical_key IS '运行内唯一逻辑键，含用例或步骤路径';
COMMENT ON COLUMN artifacts.kind IS '证据类型';
COMMENT ON COLUMN artifacts.storage_key IS '受控文件或对象存储键，不存临时签名 URL';
COMMENT ON COLUMN artifacts.mime_type IS '内容类型';
COMMENT ON COLUMN artifacts.byte_size IS '文件字节数';
COMMENT ON COLUMN artifacts.sha256 IS '完整性摘要';
COMMENT ON COLUMN artifacts.schema_version IS '原始报告或曲线 schema';
COMMENT ON COLUMN artifacts.availability IS '文件可用状态';
COMMENT ON COLUMN artifacts.expires_at IS '保留策略到期时间';
COMMENT ON COLUMN artifacts.created_at IS '创建时间，统一 UTC';

-- 性能摘要: 按指标、统计窗口和统计量保存查询所需的小体积摘要。
CREATE TABLE metric_summaries (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    component_id uuid NOT NULL,
    metric_key text NOT NULL,
    metric_version text NOT NULL,
    unit text NOT NULL,
    scope text NOT NULL,
    window_key text NOT NULL,
    statistic text NOT NULL CHECK (statistic IN ('median','p95','mean','min','max')),
    sample_count integer NOT NULL CHECK (sample_count >= 0),
    value double precision,
    missing_reason text,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, component_id, metric_key, metric_version, scope, window_key, statistic),
    FOREIGN KEY (project_id, component_id) REFERENCES run_components(project_id, id),
    CHECK ((value IS NULL AND missing_reason IS NOT NULL) OR (value IS NOT NULL AND missing_reason IS NULL)),
    CHECK (value IS NULL OR (sample_count > 0 AND value > '-Infinity'::float8 AND value < 'Infinity'::float8))
);
COMMENT ON TABLE metric_summaries IS '按指标、统计窗口和统计量保存查询所需的小体积摘要。 采样率、单位换算、窗口边界属于适配器契约；原始 series 单独归档，不逐点写业务库。';
COMMENT ON COLUMN metric_summaries.id IS '服务端生成 UUID';
COMMENT ON COLUMN metric_summaries.project_id IS '项目归属';
COMMENT ON COLUMN metric_summaries.component_id IS '性能组件';
COMMENT ON COLUMN metric_summaries.metric_key IS '有命名空间的指标键，例如 android.memory.pss';
COMMENT ON COLUMN metric_summaries.metric_version IS '指标口径版本';
COMMENT ON COLUMN metric_summaries.unit IS '显式单位，例如 MiB、ms、percent';
COMMENT ON COLUMN metric_summaries.scope IS 'app、device、page 等测量范围';
COMMENT ON COLUMN metric_summaries.window_key IS '全程或步骤窗口';
COMMENT ON COLUMN metric_summaries.statistic IS '统计量，现有 Android 判定使用 median';
COMMENT ON COLUMN metric_summaries.sample_count IS '有效样本数';
COMMENT ON COLUMN metric_summaries.value IS '缺失时为 NULL，不能补 0';
COMMENT ON COLUMN metric_summaries.missing_reason IS '缺失原因';
COMMENT ON COLUMN metric_summaries.created_at IS '创建时间，统一 UTC';

-- 基线版本: 不可变的对照版本；源运行和全部可比性信息一并保留。
CREATE TABLE baselines (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    application_id uuid NOT NULL,
    environment_id uuid NOT NULL,
    suite_version_id uuid NOT NULL,
    profile_id uuid NOT NULL,
    source_component_id uuid NOT NULL,
    name text NOT NULL,
    version integer NOT NULL CHECK (version > 0),
    metrics_snapshot jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, application_id, name, version),
    FOREIGN KEY (project_id, application_id) REFERENCES applications(project_id, id),
    FOREIGN KEY (project_id, environment_id) REFERENCES environments(project_id, id),
    FOREIGN KEY (project_id, application_id, suite_version_id) REFERENCES suite_versions(project_id, application_id, id),
    FOREIGN KEY (project_id, profile_id) REFERENCES resource_profiles(project_id, id),
    FOREIGN KEY (project_id, source_component_id) REFERENCES run_components(project_id, id),
    CHECK (jsonb_typeof(metrics_snapshot) = 'object')
);
COMMENT ON TABLE baselines IS '不可变的对照版本；源运行和全部可比性信息一并保留。 来源组件的应用、场景、环境、profile 和完整性须由创建基线事务验证；不靠跨表 CHECK。';
COMMENT ON COLUMN baselines.id IS '服务端生成 UUID';
COMMENT ON COLUMN baselines.project_id IS '项目归属';
COMMENT ON COLUMN baselines.application_id IS '应用';
COMMENT ON COLUMN baselines.environment_id IS '环境';
COMMENT ON COLUMN baselines.suite_version_id IS '场景版本';
COMMENT ON COLUMN baselines.profile_id IS '可比资源档案';
COMMENT ON COLUMN baselines.source_component_id IS '来源性能组件';
COMMENT ON COLUMN baselines.name IS '基线逻辑名';
COMMENT ON COLUMN baselines.version IS '基线修订号';
COMMENT ON COLUMN baselines.metrics_snapshot IS '指标口径、统计量、值及 schemaVersion';
COMMENT ON COLUMN baselines.created_at IS '创建时间，统一 UTC';

-- 门禁规则版本: 平台持有门槛，适配器负责正确的测量与统计。
CREATE TABLE gate_policies (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    application_id uuid NOT NULL,
    name text NOT NULL,
    version integer NOT NULL CHECK (version > 0),
    rules jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, application_id, name, version),
    FOREIGN KEY (project_id, application_id) REFERENCES applications(project_id, id),
    CHECK (jsonb_typeof(rules) = 'object')
);
COMMENT ON TABLE gate_policies IS '平台持有门槛，适配器负责正确的测量与统计。';
COMMENT ON COLUMN gate_policies.id IS '服务端生成 UUID';
COMMENT ON COLUMN gate_policies.project_id IS '项目归属';
COMMENT ON COLUMN gate_policies.application_id IS '规则适用应用';
COMMENT ON COLUMN gate_policies.name IS '逻辑规则名';
COMMENT ON COLUMN gate_policies.version IS '不可变规则版本';
COMMENT ON COLUMN gate_policies.rules IS '带 schemaVersion 的指标、单位、窗口、比较符、阈值、warn/fail 和样本下限';
COMMENT ON COLUMN gate_policies.created_at IS '创建时间，统一 UTC';

-- 门禁判定: 原始判定与后续试算分开保存；改规则不会覆盖历史结论。
CREATE TABLE gate_evaluations (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    component_id uuid NOT NULL,
    policy_id uuid NOT NULL,
    baseline_id uuid,
    mode text NOT NULL CHECK (mode IN ('original','reanalysis')),
    request_key text NOT NULL,
    verdict text NOT NULL CHECK (verdict IN ('passed','failed','not_tested')),
    reason_code text,
    checks jsonb NOT NULL DEFAULT '[]'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, request_key),
    FOREIGN KEY (project_id, component_id) REFERENCES run_components(project_id, id),
    FOREIGN KEY (project_id, policy_id) REFERENCES gate_policies(project_id, id),
    FOREIGN KEY (project_id, baseline_id) REFERENCES baselines(project_id, id),
    CHECK (jsonb_typeof(checks) = 'array'),
    CHECK (verdict <> 'not_tested' OR reason_code IS NOT NULL)
);
COMMENT ON TABLE gate_evaluations IS '原始判定与后续试算分开保存；改规则不会覆盖历史结论。 同项目外键不保证规则与基线适用当前应用；服务必须检查完整可比性。';
COMMENT ON COLUMN gate_evaluations.id IS '服务端生成 UUID';
COMMENT ON COLUMN gate_evaluations.project_id IS '项目归属';
COMMENT ON COLUMN gate_evaluations.component_id IS '性能组件';
COMMENT ON COLUMN gate_evaluations.policy_id IS '固定规则版本';
COMMENT ON COLUMN gate_evaluations.baseline_id IS '可为空，缺失时形成 not_tested 及原因';
COMMENT ON COLUMN gate_evaluations.mode IS '原始判定或后续试算';
COMMENT ON COLUMN gate_evaluations.request_key IS '判定请求幂等键';
COMMENT ON COLUMN gate_evaluations.verdict IS '三态结论';
COMMENT ON COLUMN gate_evaluations.reason_code IS '未判定原因码';
COMMENT ON COLUMN gate_evaluations.checks IS '每项实际值、阈值、单位、样本数及结果';
COMMENT ON COLUMN gate_evaluations.created_at IS '创建时间，统一 UTC';

-- 运行事件: 状态变化、步骤标记、接入事件按运行顺序追加，支持断线续看。
CREATE TABLE run_events (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    run_id uuid NOT NULL,
    sequence bigint NOT NULL CHECK (sequence > 0),
    source_key text NOT NULL,
    source_event_id text NOT NULL,
    event_type text NOT NULL,
    payload jsonb NOT NULL DEFAULT '{}'::jsonb,
    occurred_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    UNIQUE (project_id, run_id, sequence),
    UNIQUE (project_id, run_id, source_key, source_event_id),
    FOREIGN KEY (project_id, run_id) REFERENCES test_runs(project_id, id),
    CHECK (jsonb_typeof(payload) = 'object')
);
COMMENT ON TABLE run_events IS '状态变化、步骤标记、接入事件按运行顺序追加，支持断线续看。';
COMMENT ON COLUMN run_events.id IS '服务端生成 UUID';
COMMENT ON COLUMN run_events.project_id IS '项目归属';
COMMENT ON COLUMN run_events.run_id IS '运行';
COMMENT ON COLUMN run_events.sequence IS '服务端在运行锁内分配的顺序号';
COMMENT ON COLUMN run_events.source_key IS '事件生产者';
COMMENT ON COLUMN run_events.source_event_id IS '生产者侧幂等事件 ID';
COMMENT ON COLUMN run_events.event_type IS '状态、步骤标记或警告类型';
COMMENT ON COLUMN run_events.payload IS '小体积脱敏负载；完整日志走 artifacts';
COMMENT ON COLUMN run_events.occurred_at IS '事件发生时间';
COMMENT ON COLUMN run_events.created_at IS '创建时间，统一 UTC';

-- 审计事件: 记录谁修改配置、发起运行或调整规则，不承载完整业务数据。
CREATE TABLE audit_events (
    id uuid PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects(id),
    actor_ref text NOT NULL,
    action text NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    request_id text NOT NULL,
    changes jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, id),
    CHECK (jsonb_typeof(changes) = 'object')
);
COMMENT ON TABLE audit_events IS '记录谁修改配置、发起运行或调整规则，不承载完整业务数据。 只追加；审计主体与实体是否合法由授权后的业务事务写入。';
COMMENT ON COLUMN audit_events.id IS '服务端生成 UUID';
COMMENT ON COLUMN audit_events.project_id IS '项目归属';
COMMENT ON COLUMN audit_events.actor_ref IS '稳定用户或服务账号引用';
COMMENT ON COLUMN audit_events.action IS '业务动作';
COMMENT ON COLUMN audit_events.entity_type IS '目标实体类型';
COMMENT ON COLUMN audit_events.entity_id IS '目标 ID，历史追溯引用而非跨表通用外键';
COMMENT ON COLUMN audit_events.request_id IS '请求关联标识';
COMMENT ON COLUMN audit_events.changes IS '脱敏差异摘要，禁止存凭据';
COMMENT ON COLUMN audit_events.created_at IS '创建时间，统一 UTC';

-- Explicit query and concurrency indexes; add others only from measured query plans.
CREATE INDEX runs_queue ON test_runs (created_at, id) WHERE state = 'queued';
CREATE INDEX runs_project_recent ON test_runs (project_id, created_at DESC, id DESC);
CREATE INDEX runs_app_recent ON test_runs (project_id, application_id, created_at DESC, id DESC);
CREATE INDEX runs_platform_recent ON test_runs (project_id, platform, created_at DESC, id DESC);
CREATE INDEX runs_revision ON test_runs (project_id, revision_id);
CREATE INDEX runs_resource ON test_runs (project_id, resource_id);
CREATE INDEX resources_ready ON execution_resources (project_id, platform, status);
CREATE UNIQUE INDEX leases_one_live_resource ON resource_leases (project_id, resource_id) WHERE released_at IS NULL;
CREATE UNIQUE INDEX leases_one_live_run ON resource_leases (project_id, run_id) WHERE released_at IS NULL;
CREATE INDEX leases_expiry ON resource_leases (expires_at) WHERE released_at IS NULL;
CREATE UNIQUE INDEX gate_one_original ON gate_evaluations (project_id, component_id) WHERE mode = 'original';
CREATE INDEX evaluations_component ON gate_evaluations (project_id, component_id, created_at DESC);
CREATE INDEX audits_project_time ON audit_events (project_id, created_at DESC, id DESC);
CREATE INDEX artifacts_expiry ON artifacts (expires_at) WHERE availability = 'available';
CREATE UNIQUE INDEX leases_one_live_debug ON resource_leases (project_id, debug_session_id) WHERE released_at IS NULL;

COMMIT;
